import { test, expect } from '@playwright/test';

test.describe('Table Data Review - Table #table1', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
  });

  test('should display table with correct header and row count', async ({ page }) => {
    // Verify table exists
    const table = page.getByRole('table', { name: /table/i });
    await expect(table).toBeVisible();

    // Verify table has header row
    const headerRow = page.locator('[data-testid="table-header-row"]');
    await expect(headerRow).toBeVisible();

    // Verify header cells contain correct column names
    const headerCells = page.locator('[data-testid="table-header-cell"]');
    const columnNames = await headerCells.allTextContents();
    expect(columnNames).toHaveLength(4;);
    expect(columnNames).toContain('Last Name');
    expect(columnNames).toContain('First Name');
    expect(columnNames).toContain('Email');
    expect(columnNames).toContain('Due');

    // Verify table body contains 4 rows
    const tableBody = page.locator('[data-testid="table-body"]');
    const rows = page.locator('[data-testid="table-row"]').filter({ has: page.getByText('Smith') });
    const rowCount = await rows.count();
    expect(rowCount).toBe(4;);

    // Verify table has data rows
    const dataRows = page.locator('[data-testid="table-row"]').filter({ has: page.getByText('Smith') }).first();
    await expect(dataRows).toBeVisible();
  });

  test('should verify specific record data exists in the table', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table', { name: /table/i });
    await expect(table).toBeVisible();

    // Verify the row containing 'Smith' exists
    const smithRow = page.locator('[data-testid="table-row"]').filter({ has: page.getByText('Smith') }).first();
    await expect(smithRow).toBeVisible();

    // Verify the email 'jsmith@gmail.com' exists in the same row
    const emailCell = smithRow.locator('[data-testid="table-cell"]').filter({ has: page.getByText('jsmith@gmail.com') });
    await expect(emailCell).toBeVisible();

    // Verify the email cell is in the correct column (Email)
    const emailColumn = page.locator('[data-testid="table-header-cell"]').filter({ has: page.getByText('Email') });
    const emailColumnIndex = await emailColumn.evaluate((el) => {
      const cells = Array.from(el.parentElement.querySelectorAll('[data-testid="table-cell"]'));
      return cells.indexOf(el);
    });
    expect(emailColumnIndex).toBeGreaterThanOrEqual(0);

    // Verify the last name 'Smith' is in the correct column (Last Name)
    const lastNameCell = smithRow.locator('[data-testid="table-cell"]').filter({ has: page.getByText('Smith') });
    const lastNameColumnIndex = await lastNameCell.evaluate((el) => {
      const cells = Array.from(el.parentElement.querySelectorAll('[data-testid="table-cell"]'));
      return cells.indexOf(el);
    });
    expect(lastNameColumnIndex).toBeGreaterThanOrEqual(0);

    // Verify the row contains all expected data points
    const rowData = await smithRow.locator('[data-testid="table-cell"]').allTextContents();
    expect(rowData).toHaveLength(4);
    expect(rowData).toContain('Smith');
    expect(rowData).toContain('John');
    expect(rowData).toContain('jsmith@gmail.com');
    expect(rowData).toContain('2023-10-20');
  });
});
